def transform(grid):
    """Recolor the background tail beyond the rightmost foreground cell."""
    from collections import Counter
    out = [row[:] for row in grid]
    if not grid:
        return out
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        foreground = [c for c, value in enumerate(row) if value != bg]
        if foreground:
            end = max(foreground)
            for c in range(end + 1, len(row)):
                if row[c] == bg:
                    out[r][c] = 1
    return out

